`timescale 1ns/1ps
// Session-level integration test of g6lc_apu_vnfront (§4c/§6 of
// architecture/uncore/apu-vulkan-engine.md).  The front is wired to the
// real g6lc_apu_objtab, g6lc_apu_cmdrec and g6lc_apu_cmdexec; the
// front's and the executor's backend ports share each engine through a
// small two-master arbiter (plus a third, TB-owned objtab master used
// for the final RESET_CTX emptiness check).  The command stream and the
// expected record are generated by
//   python corev_apu/apu/tools/vn_golden.py --session ue_sm5_session 1
//
// Layouts:
//   cs[]        : ue_sm5_session.hex (all command streams concatenated,
//                 '%%08X' words; // name lines are $readmemh comments)
//   exp[]       : ue_sm5_session.exp, RECW=386 words per command:
//     +0  cs_base        +1  cs_len
//     +2  command type   +3  flags  bit0 reply  bit1 record
//                                   bit2 work   bit3 reset-first
//                                   bit4 gate work port
//     +4  result         +5  reply words
//     +6  live count     +7  fault
//     +8..23  expected appended record (16 words, word i=[32*i +:32])
//     +24 n_work         +25..32 work ctypes
//     +33 n_rep          +34..385 reply words
//   sentinel    : FFFFFFFF FFFFFFFF
//
// The work port is modelled with a few-cycle accept + deferred
// work_done_i.  flags bit4 holds work_ready_i low so the executor
// keeps its command-buffer pins: that makes the pinned-destroy
// negative arm deterministic (the pin lands before the first work
// record is presented; the arm's vkFreeCommandBuffers probes RETIRE
// while the pin is held).  flags bit3 marks the first command of each
// negative arm: the TB resets the whole stack there, matching the
// model's per-arm reset.
//   pay[]       : ue_sm5_session.pay -- ObjPay/cmdrec-arena write
//                 checkpoints, checked after the indexed command:
//                   tag 1 {tag, rec, n, (addr, word)*n}      ObjPay
//                   tag 2 {tag, rec, cbd, n, (waddr, word)*n}  cmdrec
//                       payload chain (absolute PayMem words)
//                   tag 3 {tag, rec, n, (byteaddr, word)*n}  aperture
//                       descriptor records (shmem, §12.3 F5)
//                 sentinel FFFFFFFF.  ObjPay contents (incl. the
//                 cmdrec chunk chains) are read back through the
//                 TB's peek of the engine's payload cache + carve.
// +ses=<name> selects a different session file set (used by the
// ObjPay-FULL arm built with -GObjPayWords=512).
module tb_g6lc_apu_vnfront;
  import g6lc_apu_vn_pkg::*;
  import g6lc_apu_cmdrec_pkg::*;
  import g6lc_apu_objtab_pkg::*;
  import g6lc_apu_objpay_pkg::*;
  import g6lc_apu_mp_pkg::*;
  import g6lc_apu_cmdexec_pkg::*;
  import g6lc_apu_sh_pkg::*;
  import g6lc_apu_vg_pkg::*;
  import g6lc_apu_vgpages_pkg::*;

  parameter int unsigned ObjPayWords = 16384;

  localparam int RECW  = 386;
  localparam int EXPW  = 386 * 256;
  localparam int PAYW  = 16384;
  localparam int Fences = 16;
  // ObjTab-V/ObjPay-V backing geometry: the ObjEntries=256 + 64 KiB
  // PayMem defaults mirror the vn_golden SLOTS/PAY_WORDS model; the
  // payfull arm overrides ObjPayWords at build time (-GObjPayWords=)
  localparam int unsigned ObjEntries  = 256;
  localparam int unsigned PayMemBytes = ObjPayWords * 4;
  localparam int unsigned PayCacheL   = 32;
  localparam logic [15:0] REP_BASE = 16'h0800;
  localparam logic [15:0] REP_LEN  = 16'd352;

  logic clk = 0, rst_ni = 0;
  int errors = 0, checks = 0, cycles = 0, cases = 0;

  // ---- front ----------------------------------------------------------
  logic               f_start = 0, f_busy, f_done;
  logic [15:0]        f_base = '0, f_len = '0;
  logic               cs_re;
  logic [15:0]        cs_addr;
  logic [31:0]        cs_rdata = '0;
  logic               cs_rv = 0, rep_wd = 0;
  logic               rep_we;
  logic [15:0]        rep_addr;
  logic [31:0]        rep_wdata;
  logic [31:0]        f_result;
  logic [15:0]        f_rwords;
  logic [3:0]         f_fault;
  // front backend ports
  logic               fot_v, fot_r, fot_cv;
  apu_objtab_req_t    fot_req;
  logic               fcr_v, fcr_r, fcr_cv;
  apu_cmdrec_req_t    fcr_req;
  logic               fsub_v, fsub_r;
  apu_cmdexec_submit_t fsub;
  logic [15:0]        f_dseq;
  logic [Fences-1:0]  f_fsig, f_flost, f_fclr, f_ffail;
  // payload stream (front -> cmdrec) + objpay port
  logic               fpay_v, fpay_r;
  logic [31:0]        fpay_d;
  logic               fop_v, fop_r, fop_cv;
  apu_objpay_req_t    fop_req;
  apu_objpay_cpl_t    fop_cpl;
  // §7b/5a-ii + G3b-ii: ShaderCore residency-manager clients —
  // vnfront (module create/destroy) ahead of cmdexec (dispatch
  // resolve), combinational grant gated by shcore's sm_busy_o; the
  // completion broadcasts — only the granted client is in its
  // wait-cpl state (mirrors vgtop's manager arbiter)
  logic               fsm_req, xsm_v;
  apu_sh_sm_req_t     fsm_pl, xsm_pl;
  apu_sh_sm_cpl_t     sm_cpl_pl;
  logic               sm_cpl;
  logic               shb;
  wire                fsm_gnt = fsm_req & ~shb;
  wire                xsm_gnt = xsm_v & ~fsm_req & ~shb;
  logic               fpg_v, fpg_r, fpg_cv;
  apu_vgpages_req_t   fpg_req;
  apu_vgpages_cpl_t   fpg_cpl;
  // F5: front descriptor-record aperture port
  logic               fap_req, fap_we, fap_done;
  logic [31:0]        fap_addr;
  logic [63:0]        fap_wdata, fap_rdata;
  logic [7:0]         fap_wstrb;
  // Enable=0 fixture
  logic               o_csre, o_repwe, o_otv, o_crcv, o_subv, o_busy,
                      o_done, o_apreq;
  logic [15:0]        o_addr, o_raddr, o_rwords;
  logic [31:0]        o_wdata, o_result;
  logic [3:0]         o_fault;
  apu_objtab_req_t    o_otreq;
  apu_cmdrec_req_t    o_crreq;
  apu_cmdexec_submit_t o_sub;
  logic [Fences-1:0]  o_fclr;
  logic               o_payv, o_opv;
  logic [31:0]        o_payd;
  apu_objpay_req_t    o_opreq;
  logic               o_smreq, o_pgv;
  apu_sh_sm_req_t     o_smpl;
  apu_vgpages_req_t   o_pgreq;

  g6lc_apu_vnfront #(.Enable(1'b1), .Fences(Fences), .CbBufs(16))
  i_front (
    .clk_i(clk), .rst_ni(rst_ni), .testmode_i(1'b0),
    .start_i(f_start), .cs_base_i(f_base), .cs_len_i(f_len),
    .rep_base_i(REP_BASE), .rep_len_i(REP_LEN), .ctx_i(8'h0),
    .cs_re_o(cs_re), .cs_addr_o(cs_addr),
    .cs_ready_i(1'b1), .cs_rvalid_i(cs_rv), .cs_rdata_i(cs_rdata),
    .cs_err_i(1'b0),
    .rep_we_o(rep_we), .rep_addr_o(rep_addr), .rep_wdata_o(rep_wdata),
    .rep_ready_i(1'b1), .rep_done_i(rep_wd), .rep_err_i(1'b0),
    .ot_req_valid_o(fot_v), .ot_req_ready_i(fot_r), .ot_req_o(fot_req),
    .ot_cpl_valid_i(fot_cv), .ot_cpl_ready_o(),
    .ot_cpl_i(ot_cpl),
    .cr_req_valid_o(fcr_v), .cr_req_ready_i(fcr_r), .cr_req_o(fcr_req),
    .cr_cpl_valid_i(fcr_cv), .cr_cpl_ready_o(),
    .cr_cpl_i(cr_cpl),
    .cr_pay_valid_o(fpay_v), .cr_pay_data_o(fpay_d),
    .cr_pay_ready_i(fpay_r),
    .op_req_valid_o(fop_v), .op_req_ready_i(fop_r),
    .op_req_o(fop_req),
    .op_cpl_valid_i(fop_cv), .op_cpl_ready_o(),
    .op_cpl_i(fop_cpl),
    .sm_req_o(fsm_req), .sm_req_pl_o(fsm_pl),
    .sm_gnt_i(fsm_gnt),
    .sm_cpl_i(sm_cpl), .sm_cpl_pl_i(sm_cpl_pl),
    .pg_req_valid_o(fpg_v), .pg_req_ready_i(fpg_r),
    .pg_req_o(fpg_req),
    .pg_cpl_valid_i(fpg_cv), .pg_cpl_ready_o(),
    .pg_cpl_i(fpg_cpl),
    .ap_req_o(fap_req), .ap_we_o(fap_we), .ap_addr_o(fap_addr),
    .ap_wdata_o(fap_wdata), .ap_wstrb_o(fap_wstrb),
    .ap_ready_i(1'b1), .ap_done_i(fap_done), .ap_rdata_i(fap_rdata),
    .ap_err_i(1'b0),
    .ex_submit_valid_o(fsub_v), .ex_submit_ready_i(fsub_r),
    .ex_submit_o(fsub),
    .ex_done_seq_i(f_dseq), .ex_fence_signaled_i(f_fsig),
    .ex_fence_lost_i(f_flost), .ex_fence_clr_o(f_fclr),
    .ex_fence_fail_o(f_ffail),
    .busy_o(f_busy), .done_o(f_done), .result_o(f_result),
    .rep_words_o(f_rwords), .fault_o(f_fault));

  g6lc_apu_vnfront_fixture #(.Enable(1'b0), .Fences(Fences))
  i_off (
    .clk_i(clk), .rst_ni(rst_ni), .testmode_i(1'b0),
    .start_i(f_start), .cs_base_i(f_base), .cs_len_i(f_len),
    .rep_base_i(REP_BASE), .rep_len_i(REP_LEN), .ctx_i(8'h0),
    .cs_re_o(o_csre), .cs_addr_o(o_addr),
    .cs_ready_i(1'b1), .cs_rvalid_i(1'b0), .cs_rdata_i('0),
    .cs_err_i(1'b0),
    .rep_we_o(o_repwe), .rep_addr_o(o_raddr), .rep_wdata_o(o_wdata),
    .rep_ready_i(1'b1), .rep_done_i(1'b0), .rep_err_i(1'b0),
    .ot_req_valid_o(o_otv), .ot_req_ready_i(1'b0), .ot_req_o(o_otreq),
    .ot_cpl_valid_i(1'b0), .ot_cpl_ready_o(), .ot_cpl_i(ot_cpl),
    .cr_req_valid_o(o_crcv), .cr_req_ready_i(1'b0), .cr_req_o(o_crreq),
    .cr_cpl_valid_i(1'b0), .cr_cpl_ready_o(), .cr_cpl_i(cr_cpl),
    .cr_pay_valid_o(o_payv), .cr_pay_data_o(o_payd),
    .cr_pay_ready_i(1'b0),
    .op_req_valid_o(o_opv), .op_req_ready_i(1'b0),
    .op_req_o(o_opreq),
    .op_cpl_valid_i(1'b0), .op_cpl_ready_o(), .op_cpl_i('0),
    .sm_req_o(o_smreq), .sm_req_pl_o(o_smpl),
    .sm_gnt_i(1'b0),
    .sm_cpl_i(1'b0), .sm_cpl_pl_i('0),
    .pg_req_valid_o(o_pgv), .pg_req_ready_i(1'b0),
    .pg_req_o(o_pgreq),
    .pg_cpl_valid_i(1'b0), .pg_cpl_ready_o(), .pg_cpl_i('0),
    .ap_req_o(o_apreq), .ap_we_o(), .ap_addr_o(), .ap_wdata_o(),
    .ap_wstrb_o(), .ap_ready_i(1'b0), .ap_done_i(1'b0),
    .ap_rdata_i('0), .ap_err_i(1'b0),
    .ex_submit_valid_o(o_subv), .ex_submit_ready_i(1'b0),
    .ex_submit_o(o_sub),
    .ex_done_seq_i('0), .ex_fence_signaled_i('0), .ex_fence_lost_i('0),
    .ex_fence_clr_o(o_fclr), .ex_fence_fail_o(),
    .busy_o(o_busy), .done_o(o_done), .result_o(o_result),
    .rep_words_o(o_rwords), .fault_o(o_fault));

  // ---- executor --------------------------------------------------------
  logic               xot_v, xot_r, xot_cv;
  apu_objtab_req_t    xot_req;
  logic               xcr_v, xcr_r, xcr_cv;
  apu_cmdrec_req_t    xcr_req;
  logic               xop_v, xop_r, xop_cv;
  apu_objpay_req_t    xop_req;
  apu_objpay_cpl_t    xop_cpl;
  logic               w_v, w_r, w_v_sh;
  apu_cmdexec_work_t  w_o;
  logic               w_done;
  apu_sh_done_t       w_done_pl;
  logic [2:0]         xdisp_slot;
  apu_sh_desc_t       xdesc;
  logic [5:0]         xpush_n;
  logic [1023:0]      xpush;
  // §5a G3b-iii: exec's indirect-fetch aperture port — dom=1 byte
  // reads served one cycle later by the shared shmem model (below)
  logic               xmp_v, xmp_rv;
  apu_mp_req_t        xmp_req;
  apu_mp_rsp_t        xmp_rsp;

  g6lc_apu_cmdexec #(.Enable(1'b1), .Fences(Fences)) i_exec (
    .clk_i(clk), .rst_ni(rst_ni), .testmode_i(1'b0),
    .submit_valid_i(fsub_v), .submit_ready_o(fsub_r), .submit_i(fsub),
    .cr_req_valid_o(xcr_v), .cr_req_ready_i(xcr_r), .cr_req_o(xcr_req),
    .cr_cpl_valid_i(xcr_cv), .cr_cpl_ready_o(), .cr_cpl_i(cr_cpl),
    .ot_req_valid_o(xot_v), .ot_req_ready_i(xot_r), .ot_req_o(xot_req),
    .ot_cpl_valid_i(xot_cv), .ot_cpl_ready_o(), .ot_cpl_i(ot_cpl),
    .op_req_valid_o(xop_v), .op_req_ready_i(xop_r), .op_req_o(xop_req),
    .op_cpl_valid_i(xop_cv), .op_cpl_ready_o(), .op_cpl_i(xop_cpl),
    .work_valid_o(w_v), .work_ready_i(w_r), .work_o(w_o),
    .work_done_i(w_done), .work_done_pl_i(w_done_pl),
    .sm_req_o(xsm_v), .sm_req_pl_o(xsm_pl),
    .sm_gnt_i(xsm_gnt),
    .sm_cpl_i(sm_cpl), .sm_cpl_pl_i(sm_cpl_pl),
    .disp_slot_o(xdisp_slot), .desc_o(xdesc),
    .push_n_o(xpush_n), .push_o(xpush),
    .done_seq_o(f_dseq),
    .fence_signaled_o(f_fsig), .fence_lost_o(f_flost),
    .fence_clr_i(f_fclr), .fence_fail_i(f_ffail), .xf_o(), .rd_o(),
    .devlost_valid_o(), .devlost_ctx_o(), .dead_o(),
    .mp_req_valid_o(xmp_v), .mp_req_ready_i(1'b1),
    .mp_req_o(xmp_req),
    .mp_rsp_valid_i(xmp_rv), .mp_rsp_i(xmp_rsp),
    .hold_i(1'b0), .idle_o(), .busy_o());

  // ---- shared backends with 4-master arbitration -----------------------
  // objtab: 0=front, 1=exec, 2=tb(final RESET_CTX), 3=shcore record
  // resolve (READSLOT) — lowest priority, mirrors vgtop's 5th requester
  logic               tb_ot = 1'b0, tot_v = 1'b0, tot_r, tot_cv;
  apu_objtab_req_t    tot_req;
  logic               ot_vld, ot_rdy, ot_cvld;
  apu_objtab_req_t    ot_req;
  apu_objtab_cpl_t    ot_cpl;
  logic               ot_busy = 1'b0;
  logic [1:0]         ot_own = '0;

  logic               shot_v, shot_r, shot_cv;
  apu_objtab_req_t    shot_req;
  wire   ot_take = ot_vld && ot_rdy;
  wire   [1:0] ot_sel = ot_busy ? ot_own
                       : (tb_ot ? 2'd2
                          : (fot_v ? 2'd0
                             : (xot_v ? 2'd1 : 2'd3)));
  assign ot_vld = ot_sel == 2'd0 ? fot_v
                : ot_sel == 2'd1 ? xot_v
                : ot_sel == 2'd2 ? tot_v : shot_v;
  assign ot_req = ot_sel == 2'd0 ? fot_req
                : ot_sel == 2'd1 ? xot_req
                : ot_sel == 2'd2 ? tot_req : shot_req;
  assign fot_r = ot_sel == 2'd0 && ot_rdy;
  assign xot_r = ot_sel == 2'd1 && ot_rdy;
  assign tot_r = ot_sel == 2'd2 && ot_rdy;
  assign shot_r = ot_sel == 2'd3 && ot_rdy;
  assign fot_cv = ot_cvld && ot_busy && ot_own == 2'd0;
  assign xot_cv = ot_cvld && ot_busy && ot_own == 2'd1;
  assign tot_cv = ot_cvld && ot_busy && ot_own == 2'd2;
  assign shot_cv = ot_cvld && ot_busy && ot_own == 2'd3;
  always @(posedge clk or negedge rst_ni)
    if (!rst_ni) begin ot_busy <= 1'b0; ot_own <= '0; end
    else if (ot_take) begin ot_busy <= 1'b1; ot_own <= ot_sel; end
    // RESET_CTX streams SWEEP completions before the final status —
    // the grant stays with the owner through the whole stream
    else if (ot_cvld && ot_cpl.status != APU_OBJTAB_SWEEP)
      ot_busy <= 1'b0;

  // cmdrec: front + exec only
  logic               cr_vld, cr_rdy, cr_cvld;
  apu_cmdrec_req_t    cr_req;
  apu_cmdrec_cpl_t    cr_cpl;
  logic               cr_busy = 1'b0, cr_own = 1'b0;
  wire   cr_take = cr_vld && cr_rdy;
  wire   cr_sel  = cr_busy ? cr_own : ~fcr_v;
  assign cr_vld = cr_sel ? xcr_v : fcr_v;
  assign cr_req = cr_sel ? xcr_req : fcr_req;
  assign fcr_r  = !cr_sel && cr_rdy;
  assign xcr_r  =  cr_sel && cr_rdy;
  assign fcr_cv = cr_cvld && cr_busy && !cr_own;
  assign xcr_cv = cr_cvld && cr_busy &&  cr_own;
  always @(posedge clk or negedge rst_ni)
    if (!rst_ni) begin cr_busy <= 1'b0; cr_own <= 1'b0; end
    else if (cr_take) begin cr_busy <= 1'b1; cr_own <= cr_sel; end
    else if (cr_cvld) cr_busy <= 1'b0;

  // ---- objmem plumbing (ObjTab-V/ObjPay-V DRAM backing) ----------
  logic         omt_v, omt_r, omt_rv;
  apu_omt_req_t omt_req;
  apu_omt_rsp_t omt_rsp;
  logic         omp_v, omp_r, omp_rv;
  apu_omp_req_t omp_req;
  apu_omp_rsp_t omp_rsp;
  logic         mp_v, mp_r, mp_rv;
  apu_mp_req_t  mp_req;
  apu_mp_rsp_t  mp_rsp;
  logic [15:0]  obj_live;

  g6lc_apu_objtab #(.Enable(1'b1), .ObjEntries(ObjEntries),
                    .MaxCtx(32)) i_obj (
    .clk_i(clk), .rst_ni(rst_ni), .testmode_i(1'b0),
    .req_valid_i(ot_vld), .req_ready_o(ot_rdy), .req_i(ot_req),
    .cpl_valid_o(ot_cvld), .cpl_ready_i(1'b1), .cpl_o(ot_cpl),
    .live_o(obj_live),
    .omt_req_valid_o(omt_v), .omt_req_ready_i(omt_r),
    .omt_req_o(omt_req),
    .omt_rsp_valid_i(omt_rv), .omt_rsp_i(omt_rsp));
  // §5a G3b-iii: PayMem-resident command buffers — cmdrec owns a
  // fourth ObjPay client for its descriptor/chunk traffic
  logic            cop_v, cop_r, cop_cv;
  apu_objpay_req_t cop_req;
  g6lc_apu_cmdrec #(.Enable(1'b1), .CbOpen(4))
  i_rec (
    .clk_i(clk), .rst_ni(rst_ni), .testmode_i(1'b0),
    .req_valid_i(cr_vld), .req_ready_o(cr_rdy), .req_i(cr_req),
    .cpl_valid_o(cr_cvld), .cpl_ready_i(1'b1), .cpl_o(cr_cpl),
    .pay_valid_i(fpay_v), .pay_data_i(fpay_d),
    .pay_ready_o(fpay_r),
    .op_req_valid_o(cop_v), .op_req_ready_i(cop_r),
    .op_req_o(cop_req),
    .op_cpl_valid_i(cop_cv), .op_cpl_ready_o(), .op_cpl_i(op_cpl));

  // §7b/5a-ii + G3b-ii/iii: objpay shared front(0)/exec(1)/cmdrec(2)/
  // shcore-FILL(3), vgtop priority order.  The owner latch is sticky
  // (set at accept, replaced by the next accept) so a READN burst's
  // per-word completions all route to the requester — req_ready stays
  // low for the whole burst, so no new owner can intervene.
  logic               op_vld, op_rdy, op_cvld;
  apu_objpay_req_t    op_req;
  apu_objpay_cpl_t    op_cpl;
  logic [1:0]         op_own = '0;
  logic               sop_v, sop_r;
  apu_objpay_req_t    sop_req;
  wire   op_take = op_vld && op_rdy;
  wire   [1:0] op_sel = fop_v ? 2'd0
                       : (xop_v ? 2'd1
                          : (cop_v ? 2'd2 : 2'd3));
  assign op_vld = fop_v | xop_v | cop_v | sop_v;
  assign op_req = fop_v ? fop_req
                : xop_v ? xop_req
                : cop_v ? cop_req : sop_req;
  assign fop_r  = fop_v && op_rdy;
  assign xop_r  = xop_v && !fop_v && op_rdy;
  assign cop_r  = cop_v && !fop_v && !xop_v && op_rdy;
  assign sop_r  = sop_v && !fop_v && !xop_v && !cop_v && op_rdy;
  assign fop_cv = op_cvld && op_own == 2'd0;
  assign xop_cv = op_cvld && op_own == 2'd1;
  assign cop_cv = op_cvld && op_own == 2'd2;
  assign fop_cpl = op_cpl;
  assign xop_cpl = op_cpl;
  always @(posedge clk or negedge rst_ni)
    if (!rst_ni) op_own <= '0;
    else if (op_take) op_own <= op_sel;

  g6lc_apu_objpay #(.Enable(1'b1), .PayMemBytes(PayMemBytes)) i_pay (
    .clk_i(clk), .rst_ni(rst_ni), .testmode_i(1'b0),
    .req_valid_i(op_vld), .req_ready_o(op_rdy), .req_i(op_req),
    .cpl_valid_o(op_cvld), .cpl_ready_i(1'b1), .cpl_o(op_cpl),
    .omp_req_valid_o(omp_v), .omp_req_ready_i(omp_r),
    .omp_req_o(omp_req),
    .omp_rsp_valid_i(omp_rv), .omp_rsp_i(omp_rsp));

  // objmem owns the ObjTab/ObjPay carve above the managed window
  g6lc_apu_objmem #(.Enable(1'b1), .ObjEntries(ObjEntries),
                    .PayMemBytes(PayMemBytes),
                    .PayCacheLines(PayCacheL)) i_omm (
    .clk_i(clk), .rst_ni(rst_ni), .testmode_i(1'b0),
    .omt_req_valid_i(omt_v), .omt_req_ready_o(omt_r),
    .omt_req_i(omt_req),
    .omt_rsp_valid_o(omt_rv), .omt_rsp_o(omt_rsp),
    .omp_req_valid_i(omp_v), .omp_req_ready_o(omp_r),
    .omp_req_i(omp_req),
    .omp_rsp_valid_o(omp_rv), .omp_rsp_o(omp_rsp),
    .mp_req_valid_o(mp_v), .mp_req_ready_i(mp_r),
    .mp_req_o(mp_req),
    .mp_rsp_valid_i(mp_rv), .mp_rsp_i(mp_rsp));

  // aperture responder over the static carve window only;
  // +mp_lat_min/max=1..8 stress the engine round-trips
  localparam logic [63:0] OM_PAY_OFF =
      apu_objmem_pay_off(ObjEntries);
  tb_apu_mp_mem #(.N(1), .GMW(1), .APW(0),
                  .PWB(32'(g6lc_apu_objtab_pkg::APU_OBJMEM_OFF >> 2)),
                  .PPW(32'((OM_PAY_OFF + 64'(PayMemBytes) -
                            g6lc_apu_objtab_pkg::APU_OBJMEM_OFF) >> 2) +
                        64))
      i_mem (
    .clk_i(clk), .rst_ni(rst_ni),
    .req_valid_i(mp_v), .req_ready_o(mp_r), .req_i('{mp_req}),
    .rsp_valid_o(mp_rv), .rsp_o('{mp_rsp}));

  // ObjPay-V architectural read view: the write-merge buffer in
  // objpay (a completed WRITE may still sit there), then objmem's
  // write-back payload cache, then the DRAM carve (dense index = byte
  // offset from the carve base in words, APW=0/PWB=OBJMEM_OFF>>2)
  function automatic logic [31:0] pay_peek(input logic [31:0] waddr);
    if (i_pay.gen_on.wb_v_q &&
        i_pay.gen_on.wb_line_q == (waddr >> 4) &&
        i_pay.gen_on.wb_bm_q[waddr & 15])
      return i_pay.gen_on.wb_data_q[32 * (waddr & 15) +: 32];
    for (int i = 0; i < PayCacheL; i++)
      if (i_omm.gen_on.pc_vld_q[i] &&
          i_omm.gen_on.pc_ln_q[i] ==
            $bits(i_omm.gen_on.pc_ln_q[i])'(waddr >> 4))
        return i_omm.gen_on.i_pc.sram[i][32 * (waddr & 15) +: 32];
    return i_mem.apm[32'(OM_PAY_OFF >> 2) + waddr -
                     32'(g6lc_apu_objtab_pkg::APU_OBJMEM_OFF >> 2)];
  endfunction

  // §7b/5a-ii: real vgpages at the shipped geometry (front is the
  // only master in this TB); the guest/private split must match the
  // vn_golden model so ALLOC_PRIV pool bases agree with the tapes
  g6lc_apu_vgpages #(.Enable(1'b1), .Pages(APU_VG_PAGES),
                     .PageBytes(APU_VG_PAGE_BYTES),
                     .GuestPages(APU_VG_GUEST_PAGES))
  i_vgp (
    .clk_i(clk), .rst_ni(rst_ni), .testmode_i(1'b0),
    .req_valid_i(fpg_v), .req_ready_o(fpg_r), .req_i(fpg_req),
    .cpl_valid_o(fpg_cv), .cpl_ready_i(1'b1), .cpl_o(fpg_cpl));

  // §7b/5a-ii: real ShaderCore -- front drives module staging/commit
  // and the slot manager, exec drives the work port + dispatch
  // sideband; done feeds the executor's completion input
  logic [63:0] shm_addr, shm_wdata, shm_rdata;
  logic        shm_re, shm_we;
  logic [7:0]  shm_wstrb;
  // functional geometry: real corpus modules need default ShaderWords
  // (the synth small screen rejects every vector module)
  g6lc_apu_shcore #(.Enable(1'b1)) i_shc (
    .clk_i(clk), .rst_ni(rst_ni), .testmode_i(1'b0),
    // G3b-ii: staging/commit is internal to the FILL engine; the
    // external ports are a backdoor the front no longer drives
    .wr_en_i(1'b0), .wr_slot_i('0), .wr_addr_i('0), .wr_data_i('0),
    .commit_i(1'b0), .commit_pl_i('0),
    .c_busy_o(), .c_done_o(), .c_done_pl_o(),
    .retire_i(1'b0), .retire_slot_i(3'h0),
    .sm_req_i(fsm_gnt | xsm_gnt),
    .sm_req_pl_i(fsm_gnt ? fsm_pl : xsm_pl),
    .sm_cpl_o(sm_cpl), .sm_cpl_pl_o(sm_cpl_pl),
    .sm_busy_o(shb),
    .op_req_valid_o(sop_v), .op_req_ready_i(sop_r),
    .op_req_o(sop_req),
    .op_cpl_valid_i(op_cvld && op_own == 2'd3),
    .op_cpl_i(op_cpl),
    .work_i(w_v_sh), .work_ready_o(w_r_sh),
    .work_ctype_i(w_o.ctype), .work_imm_i(w_o.rec.imm),
    .disp_slot_i(xdisp_slot), .desc_i(xdesc),
    .push_n_i(xpush_n), .push_i(xpush),
    .busy_o(), .done_o(w_done), .done_pl_o(w_done_pl),
    .mem_re_o(shm_re), .mem_we_o(shm_we), .mem_addr_o(shm_addr),
    .mem_wdata_o(shm_wdata), .mem_wstrb_o(shm_wstrb),
    .mem_ready_i(1'b1), .mem_rvalid_i(shm_rv),
    .mem_rdata_i(shm_rdata), .mem_err_i(1'b0),
    .ot_req_valid_o(shot_v), .ot_req_ready_i(shot_r),
    .ot_req_o(shot_req),
    .ot_cpl_valid_i(shot_cv), .ot_cpl_ready_o(), .ot_cpl_i(ot_cpl));

  // shader-side aperture: byte-addressed SHM window, handshake
  // port (ready=1, rvalid next cycle)
  localparam int SHAPB = 1 << 21;
  // §12.3 F5: pool record stores land in the device-private arena
  // [APU_VG_GUEST_BYTES, APU_VG_SHM_BYTES) — the dense model covers
  // the low window plus that range via the compressed apb() view
  localparam int PV0   = 32'(g6lc_apu_vg_pkg::APU_VG_GUEST_BYTES);
  localparam int PVN   = g6lc_apu_vg_pkg::APU_VG_PRIV_PAGES *
                         g6lc_apu_vg_pkg::APU_VG_PAGE_BYTES;
  localparam int SHAPN = SHAPB + PVN;
  logic [7:0] shmem [SHAPN];
  function automatic int unsigned apb(input int unsigned a);
    if (a < SHAPB) return a;
    if (a >= PV0 && a < PV0 + PVN) return SHAPB + (a - PV0);
    $fatal(1, "aperture byte %08x past TB model", a);
    return 0;
  endfunction
  logic       shm_rv = 0;
  always @(posedge clk or negedge rst_ni) begin
    if (!rst_ni) begin
      shm_rv <= 1'b0; shm_rdata <= '0;
      fap_done <= 1'b0; fap_rdata <= '0;
    end else begin
      shm_rv <= 1'b0;
      if (shm_re) begin
        shm_rv <= 1'b1;
        for (int b = 0; b < 8; b++)
          shm_rdata[b*8 +: 8] <= shmem[apb(32'(shm_addr) + 32'(b))];
      end
      if (shm_we) begin
        shm_rv <= 1'b1;
        for (int b = 0; b < 8; b++)
          if (shm_wstrb[b]) shmem[apb(32'(shm_addr) + 32'(b))] <=
                            shm_wdata[b*8 +: 8];
      end
      // F5: front descriptor-record port — same aperture array,
      // ready=1 / done next cycle (mirrors the vnpump OW_FAP arbiter)
      fap_done <= 1'b0;
      if (fap_req) begin
        fap_done <= 1'b1;
        if (fap_we) begin
          for (int b = 0; b < 8; b++)
            if (fap_wstrb[b])
              shmem[apb(fap_addr + 32'(b))] <= fap_wdata[b*8 +: 8];
        end else begin
          for (int b = 0; b < 8; b++)
            fap_rdata[b*8 +: 8] <= shmem[apb(fap_addr + 32'(b))];
        end
      end
      // G3b-iii: executor indirect fetch — dom=1 aperture reads land
      // in the same array so buffer contents staged by front writes
      // are coherent with what the executor reads back
      xmp_rv <= 1'b0;
      if (xmp_v) begin
        if (xmp_req.we || !xmp_req.dom)
          $fatal(1, "exec mp: unsupported write/guest-domain req");
        xmp_rv <= 1'b1;
        xmp_rsp.err <= 1'b0;
        for (int b = 0; b < 8; b++)
          xmp_rsp.rdata[b*8 +: 8] <=
              shmem[apb(32'(xmp_req.addr) + 32'(b))];
      end
    end
  end

  // ---- memories --------------------------------------------------------
  logic [31:0] cs   [65536];
  logic [31:0] expm [EXPW];
  logic [31:0] paym [PAYW];
  logic [31:0] repm [4096];
  // handshake CS/reply models: ready=1, response/done next cycle
  always @(posedge clk or negedge rst_ni) begin
    if (!rst_ni) begin
      cs_rv <= 0; rep_wd <= 0; cs_rdata <= '0;
    end else begin
      cs_rv <= 1'b0; rep_wd <= 1'b0;
      if (cs_re)  begin cs_rv <= 1'b1; cs_rdata <= cs[cs_addr]; end
      if (rep_we) begin rep_wd <= 1'b1; repm[rep_addr[11:0]] <= rep_wdata; end
    end
  end

  always #5 clk = ~clk;
  always @(posedge clk) cycles++;

  // disabled-engine quiet check
  always @(negedge clk) begin
    if (o_csre || o_repwe || o_otv || o_crcv || o_subv || o_busy ||
        o_done || o_fclr !== '0 || o_result !== '0 ||
        o_payv || o_opv || o_payd !== '0 || o_opreq !== '0 ||
        o_smreq || o_smpl !== '0 ||
        o_pgv || o_pgreq !== '0 || o_apreq ||
        o_rwords !== '0 || o_fault !== '0)
      $fatal(1, "disabled vnfront active");
  end

  // ---- work port (exec -> real shcore; TB gates the pass-through) ---
  logic        work_gate = 1'b0;
  logic        w_r_sh;
  logic [31:0] ew_q [256];
  int          ew_head = 0, ew_tail = 0;
  wire         work_pass = !work_gate && (cycles % 5) != 4;
  assign w_v_sh = w_v && work_pass;
  assign w_r    = w_r_sh && work_pass;

  always @(posedge clk) begin
    if (w_v && w_r) begin
      checks++;
      if (ew_head == ew_tail) begin
        errors++;
        $display("FAIL: unanticipated work ctype=%08x", w_o.ctype);
      end else if (w_o.ctype !== ew_q[ew_head]) begin
        errors++;
        $display("FAIL: work ctype %08x expected %08x",
                 w_o.ctype, ew_q[ew_head]);
      end
      ew_head = ew_head + 1;
    end
  end

  // ---- record-append monitor (front cmdrec port) -----------------------
  // §5a G3b-iii: the recorder stamps the stored record's imm[7]
  // with the payload's absolute PayMem word address — the request
  // view shows imm[7]==0, so the monitor shadows each descriptor's
  // chain state ({pay tail chunk, next payload word, next record
  // row}) and snoops the cmdrec ObjPay client's ALLOC completions to
  // predict it.  APPEND internals run record-ALLOC then payload-
  // ALLOC; a pool walk visits every descriptor with a READN(d+8,4),
  // which is how RESET_POOL/DESTROY_POOL clears the shadows.  BEGIN/
  // RESET clear too; cursors advance only on an OK completion (FULL
  // drops the record; a linked-but-unwritten chunk keeps its row).
  apu_cmdrec_rec_t last_rec;
  int              appends = 0;
  int              sh_payt [int];   // cbd -> pay tail-chunk base
  int              sh_ptop [int];   // cbd -> next payload word
  int              sh_row  [int];   // cbd -> next record row (1..)
  bit              sh_recs [int];   // cbd -> record chain exists
  logic [31:0]     pend_cbd_q;
  logic [15:0]     pend_pay_q;
  logic            pend_app_q, pend_ral_q, pend_pal_q;
  logic            pend_pool_q, pool_walk_q;
  apu_objpay_op_e  cop_opc_q;    // last accepted cmdrec ObjPay op
  always @(posedge clk or negedge rst_ni)
    if (!rst_ni) begin
      pend_app_q <= 1'b0; pend_pool_q <= 1'b0;
      pend_ral_q <= 1'b0; pend_pal_q <= 1'b0;
      cop_opc_q  <= APU_OBJPAY_OP_READ;
      pend_cbd_q <= '0; pend_pay_q <= '0;
      pool_walk_q <= 1'b0;
      sh_payt.delete(); sh_ptop.delete();
      sh_row.delete();  sh_recs.delete();
    end else begin
      if (fcr_v && fcr_r) begin
        // F2: while a pool walk streams SWEEP interims, no further
        // cmdrec request may issue — vnfront must hold off until the
        // final non-SWEEP completion
        if (pool_walk_q) begin
          errors++;
          $display("FAIL: cmdrec request op=%0d during pool walk",
                   fcr_req.op);
        end
        if (fcr_req.op == APU_CMDREC_OP_RESET_POOL ||
            fcr_req.op == APU_CMDREC_OP_DESTROY_POOL)
          pool_walk_q <= 1'b1;
        if (fcr_req.op == APU_CMDREC_OP_BEGIN) begin
          // BEGIN frees any old chains then ALLOCs a fresh record
          // chunk; the shadow just needs the post-BEGIN state
          sh_recs[fcr_req.cbd] = 1;
          sh_row [fcr_req.cbd] = 1;
          sh_payt[fcr_req.cbd] = 0;
          sh_ptop[fcr_req.cbd] = 0;
        end else if (fcr_req.op == APU_CMDREC_OP_RESET) begin
          sh_recs.delete(fcr_req.cbd);
          sh_row .delete(fcr_req.cbd);
          sh_payt.delete(fcr_req.cbd);
          sh_ptop.delete(fcr_req.cbd);
        end else if (fcr_req.op == APU_CMDREC_OP_RESET_POOL ||
                     fcr_req.op == APU_CMDREC_OP_DESTROY_POOL) begin
          // every visited descriptor announces itself with a
          // READN(cbd+8,4) on the ObjPay port — cleared below
          pend_pool_q <= 1'b1;
        end else if (fcr_req.op == APU_CMDREC_OP_APPEND) begin
          automatic bit ex = sh_recs.exists(fcr_req.cbd);
          automatic bit ral = !ex || sh_row[fcr_req.cbd] > 63;
          automatic bit pal =
              fcr_req.pay_n != 16'h0 &&
              (!sh_payt.exists(fcr_req.cbd) ||
               sh_payt[fcr_req.cbd] == 0 ||
               sh_ptop[fcr_req.cbd] + int'(fcr_req.pay_n) >
               sh_payt[fcr_req.cbd] + 1024);
          last_rec   <= fcr_req.rec;
          if (fcr_req.pay_n != 16'h0 && !pal)
            last_rec.imm[7] <= 32'(sh_ptop[fcr_req.cbd]);
          pend_app_q <= 1'b1;
          pend_cbd_q <= fcr_req.cbd;
          pend_pay_q <= fcr_req.pay_n;
          pend_ral_q <= ral;
          pend_pal_q <= pal;
          appends     = appends + 1;
        end
      end
      // the walk ends at the first non-SWEEP completion
      if (fcr_cv && cr_cpl.status != APU_CMDREC_SWEEP)
        pool_walk_q <= 1'b0;
      if (pend_pool_q && cop_v && cop_r &&
          cop_req.op == APU_OBJPAY_OP_READN && cop_req.words == 32'd4)
      begin
        // pool walk visiting a descriptor: cbd = addr - 8
        automatic int cd = int'(cop_req.addr) - 8;
        sh_recs.delete(cd); sh_row.delete(cd);
        sh_payt.delete(cd); sh_ptop.delete(cd);
      end
      if (cop_v && cop_r) cop_opc_q <= cop_req.op;
      if (pend_app_q && cop_cv &&
          cop_opc_q == APU_OBJPAY_OP_ALLOC &&
          op_cpl.status == APU_OBJPAY_OK) begin
        // ALLOC completions arrive in request order: record chunk
        // first, payload chunk second
        if (pend_ral_q) begin
          pend_ral_q <= 1'b0;
          sh_recs[pend_cbd_q] = 1;
          sh_row [pend_cbd_q] = 1;
        end else if (pend_pal_q) begin
          pend_pal_q <= 1'b0;
          last_rec.imm[7]      <= op_cpl.base + 32'd1;
          sh_payt[pend_cbd_q]  = int'(op_cpl.base);
          sh_ptop[pend_cbd_q]  = int'(op_cpl.base) + 1;
        end
      end else if (pend_app_q && cop_cv &&
                   cop_opc_q == APU_OBJPAY_OP_ALLOC) begin
        // a failed ALLOC still consumes its due slot in the order
        if (pend_ral_q)      pend_ral_q <= 1'b0;
        else if (pend_pal_q) pend_pal_q <= 1'b0;
      end
      if (pend_app_q && fcr_cv) begin
        pend_app_q <= 1'b0;
        if (cr_cpl.status == APU_CMDREC_OK) begin
          sh_row[pend_cbd_q] = sh_row.exists(pend_cbd_q)
                               ? sh_row[pend_cbd_q] + 1 : 2;
          if (pend_pay_q != 16'h0 && sh_ptop.exists(pend_cbd_q))
            sh_ptop[pend_cbd_q] = sh_ptop[pend_cbd_q] +
                                  int'(pend_pay_q);
        end
      end
      if (pend_pool_q && fcr_cv &&
          cr_cpl.status != APU_CMDREC_SWEEP)
        pend_pool_q <= 1'b0;
    end
  function automatic logic [31:0] ev(input int rec, input int w);
    return expm[rec * RECW + w];
  endfunction

  // ---- debug: backend transaction trace (+define+VNFRONT_TRACE) ------
`ifdef VNFRONT_TRACE
  always @(posedge clk) begin
    if (ot_take)
      $display("OT req own=%0d op=%0d id=%x kind=%0d pid=%x",
               ot_sel, ot_req.op, ot_req.id, ot_req.kind,
               ot_req.parent_id);
    if (ot_cvld)
      $display("OT cpl own=%0d st=%0d h=%x", ot_own, ot_cpl.status,
               ot_cpl.handle);
    if (cr_take)
      $display("CR req own=%0d op=%0d buf=%0d", cr_sel, cr_req.op,
               cr_req.cbuf);
    if (cr_cvld)
      $display("CR cpl own=%0d st=%0d cnt=%0d", cr_own, cr_cpl.status,
               cr_cpl.count);
    if (fsm_req && fsm_gnt)
      $display("SM req op=%0d slot=%0d hnd=%08x chunk=%0d w=%0d",
               fsm_pl.op, fsm_pl.slot, fsm_pl.handle, fsm_pl.chunk,
               fsm_pl.words);
    if (sm_cpl)
      $display("SM cpl ok=%0d busy=%0d slot=%0d fault=%08x",
               sm_cpl_pl.ok, sm_cpl_pl.busy, sm_cpl_pl.slot,
               sm_cpl_pl.fault);
  end
`endif

  task automatic check(input string name, input logic ok);
    checks++;
    if (ok !== 1'b1) begin
      errors++;
      $display("FAIL rec %0d: %s", cases, name);
      if (errors > 16) $fatal(1, "too many errors");
    end
  endtask

  // ---- final RESET_CTX through the TB objtab master --------------------
  task automatic reset_ctx();
    @(negedge clk);
    tb_ot = 1'b1;
    tot_v = 1'b1;
    tot_req = '{op: APU_OBJTAB_OP_RESET_CTX, ctx: 8'h0, default: '0};
    @(posedge clk);
    while (!tot_r) @(posedge clk);
    @(negedge clk); tot_v = 1'b0;
    while (!tot_cv) @(negedge clk);
    // drain interim SWEEP completions to the final OK
    while (ot_cpl.status == APU_OBJTAB_SWEEP) begin
      @(negedge clk);
      while (!tot_cv) @(negedge clk);
    end
    @(negedge clk);
    tb_ot = 1'b0;
  endtask

  int rec, tmo, payp, npw;
  logic [31:0] fl, pw_addr, pw_cbuf;
  logic [511:0] exp_rec;
  int app0, nwork, nrep;
  string ses;

  initial begin
    if (!$value$plusargs("ses=%s", ses)) ses = "ue_sm5_session";
    for (int i = 0; i < $size(cs); i++) cs[i] = '0;
    for (int i = 0; i < $size(expm); i++) expm[i] = '0;
    for (int i = 0; i < $size(paym); i++) paym[i] = '0;
    for (int i = 0; i < $size(repm); i++) repm[i] = '0;
    for (int i = 0; i < SHAPN; i++) shmem[i] = '0;
    $readmemh($sformatf("vn_vectors/%s.hex", ses), cs, 0);
    $readmemh($sformatf("vn_vectors/%s.exp", ses), expm, 0);
    $readmemh($sformatf("vn_vectors/%s.pay", ses), paym, 0);
    @(negedge clk); rst_ni = 1'b0;
    repeat (3) @(negedge clk); rst_ni = 1'b1;
    repeat (2) @(negedge clk);

    rec = 0;
    payp = 0;
    while (ev(rec, 0) !== 32'hFFFFFFFF) begin
      fl = ev(rec, 3);
      if ((fl & 32'd8) != 0) begin
        // negative arm: reset the whole stack, then let it settle
        @(negedge clk); rst_ni = 1'b0;
        repeat (3) @(negedge clk); rst_ni = 1'b1;
        repeat (2) @(negedge clk);
        ew_head = 0; ew_tail = 0; appends = 0;
        work_gate = 1'b0;
      end
      // push the expected work sequence up front so an eager executor
      // cannot issue before the expectation exists
      nwork = int'(ev(rec, 24));
      for (int i = 0; i < nwork; i++) begin
        ew_q[ew_tail] = ev(rec, 25 + i);
        ew_tail++;
      end
      work_gate = (fl & 32'd16) != 32'd0;
      app0 = appends;

      @(negedge clk);
      f_base = 16'(ev(rec, 0));
      f_len  = 16'(ev(rec, 1));
      f_start = 1'b1;
      @(posedge clk);
      @(negedge clk); f_start = 1'b0;
      tmo = 0;
      while (!f_done) begin
        @(negedge clk);
        tmo++;
        if (tmo > 20000) begin
          // timeout forensics: front/cmdrec/exec/objtab/objpay FSM
          // states plus the in-flight request beats — hierarchical
          // probes are brittle by design (rename breaks the TB
          // build, which is the intended tripwire)
          $display("hang rec %0d: front.state=%0d rec.state=%0d exec.state=%0d ot.state=%0d pay.state=%0d",
                   rec, i_front.gen_on.state_q, i_rec.gen_on.state_q,
                   i_exec.gen_on.state_q, i_obj.gen_on.state_q,
                   i_pay.gen_on.state_q);
          $display("  front.crr.op=%0d rec.req.op=%0d rec.req.cbd=%08x front.crr.cbd=%08x op_own=%0d",
                   i_front.gen_on.crr_q.op, i_rec.gen_on.req_q.op,
                   i_rec.gen_on.req_q.cbd, i_front.gen_on.crr_q.cbd,
                   op_own);
          $display("  rec.opq.op=%0d addr=%08x words=%0d obi=%0d opn=%0d fop_v=%b xop_v=%b cop_v=%b sop_v=%b",
                   i_rec.gen_on.opq_q.op, i_rec.gen_on.opq_q.addr,
                   i_rec.gen_on.opq_q.words, i_rec.gen_on.obi_q,
                   i_rec.gen_on.opn_q, fop_v, xop_v, cop_v, sop_v);
          $display("  pay req.op=%0d addr=%08x words=%0d nb_n=%0d nb_i=%0d nb_off=%0d cvld=%b",
                   i_pay.gen_on.req_q.op, i_pay.gen_on.req_q.addr,
                   i_pay.gen_on.req_q.words, i_pay.gen_on.nb_n_q,
                   i_pay.gen_on.nb_i_q, i_pay.gen_on.nb_off_q,
                   op_cvld);
          $fatal(1, "timeout rec %0d", rec);
        end
      end
      cases++;

      check($sformatf("result %08x exp %08x", f_result, ev(rec, 4)),
            f_result === ev(rec, 4));
      check("fault", f_fault === 4'(ev(rec, 7)));
      if ((fl & 32'd1) != 0) begin
        check("rep_words", f_rwords === 16'(ev(rec, 5)));
        nrep = int'(ev(rec, 33));
        for (int i = 0; i < nrep; i++)
          check($sformatf("rep[%0d]", i),
                repm[12'(REP_BASE + 16'(i))] === ev(rec, 34 + i));
      end else begin
        check("norep", f_rwords === 16'h0);
      end
      check($sformatf("live %0d exp %0d",
                      obj_live, ev(rec, 6)),
            obj_live === 16'(ev(rec, 6)));
      if ((fl & 32'd2) != 0) begin
        for (int i = 0; i < 16; i++)
          exp_rec[32 * i +: 32] = ev(rec, 8 + i);
        check("append seen", appends > app0);
        if (last_rec !== exp_rec) begin
          for (int i = 0; i < 16; i++)
            $display("  rec word %0d got %08x exp %08x", i,
                     last_rec[32 * i +: 32], exp_rec[32 * i +: 32]);
        end
        check("record", last_rec === exp_rec);
      end
      // §7b payload checkpoints written by this command
      while (paym[payp] !== 32'hFFFFFFFF &&
             paym[payp + 1] === 32'(rec)) begin
        if (paym[payp] == 32'd1) begin
          npw = int'(paym[payp + 2]);
          payp += 3;
          for (int i = 0; i < npw; i++) begin
            pw_addr = paym[payp];
            check($sformatf("objpay[%0d]", pw_addr),
                  pay_peek(pw_addr) === paym[payp + 1]);
            payp += 2;
          end
        end else if (paym[payp] == 32'd2) begin
          // §5a G3b-iii: cmdrec payloads live in the buffer's ObjPay
          // chunk chain — the checkpoint word after `rec` is the
          // descriptor word address (diagnostics only); each (idx,
          // word) pair is an absolute PayMem word address
          pw_cbuf = paym[payp + 2];
          npw = int'(paym[payp + 3]);
          payp += 4;
          for (int i = 0; i < npw; i++) begin
            pw_addr = paym[payp];
            check($sformatf("paychain[@%0d:+%0d] @%0d got %08x exp %08x",
                            pw_cbuf, i, pw_addr,
                            pay_peek(pw_addr), paym[payp + 1]),
                  pay_peek(pw_addr) === paym[payp + 1]);
            payp += 2;
          end
        end else if (paym[payp] == 32'd3) begin
          // §12.3 F5: aperture-resident descriptor records — {byte
          // address, word32} pairs against the TB's shmem model
          npw = int'(paym[payp + 2]);
          payp += 3;
          for (int i = 0; i < npw; i++) begin
            pw_addr = paym[payp];
            check($sformatf("aperture[%0d]", pw_addr),
                  {shmem[apb(pw_addr + 3)], shmem[apb(pw_addr + 2)],
                   shmem[apb(pw_addr + 1)], shmem[apb(pw_addr)]}
                  === paym[payp + 1]);
            payp += 2;
          end
        end else begin
          $fatal(1, "bad .pay tag %08x at %0d", paym[payp], payp);
        end
      end
      rec++;
    end

    // ---- final: ObjTab must empty under RESET_CTX -----------------------
    reset_ctx();
    check("reset_ctx status", ot_cpl.status == APU_OBJTAB_OK);
    check("reset_ctx pinned==0", ot_cpl.handle[15:0] === 16'h0);
    repeat (4) @(negedge clk);
    check("objtab empty", obj_live === 16'h0);
    check("all work consumed", ew_head == ew_tail);
    check("objpay chunks drained",
          i_pay.gen_on.used_q === 0);

    if (errors == 0)
      $display("PASS tb_g6lc_apu_vnfront cases=%0d checks=%0d cycles=%0d",
               cases, checks, cycles);
    else
      $display({"FAIL tb_g6lc_apu_vnfront cases=%0d errors=%0d ",
                "checks=%0d cycles=%0d"}, cases, errors, checks, cycles);
    $finish;
  end
endmodule
